    /// <summary>
    /// Checks whether the current user can post a story on behalf of a chat; requires can_post_stories administrator right for supergroup and channel chats
    /// </summary>
    public Task<TdLib.TdApi.Objects.CanPostStoryResult> CanPostStoryAsync(long chatId = default)
    {

           using var activity =  StartCallActivity("CanPostStoryAsync", typeof(CanPostStory).FullName ?? "CanPostStoryAsync");

           try
           {
             return client.CanPostStoryAsync(chatId);
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
}
